svg.script:
(function () {
  var frame = document.getElementById('proxyfox');
  frame.addEventListener('load', function () { try { frame.focus(); } catch (e) {} });

  // Multi-threading (and a saved profile) needs this page and Proxyfox cross-origin isolated,
  // which this host can't do with headers: sw.js adds them to everything it serves. The first
  // visit registers it, and once it takes over, the page reloads once so it runs isolated.
  if (self.crossOriginIsolated || !('serviceWorker' in navigator) || !self.isSecureContext) return;
  var KEY = 'proxyfox-svg-isolated-reload';
  var tried = false;
  try { tried = sessionStorage.getItem(KEY) === '1'; } catch (e) {}
  navigator.serviceWorker.register('sw.js').catch(function () {});
  if (tried) return; // reloaded once already: don't loop if isolation still isn't on
  var reload = function () {
    try { sessionStorage.setItem(KEY, '1'); } catch (e) {}
    location.reload();
  };
  if (navigator.serviceWorker.controller) reload(); // controlled, yet not isolated: an older page copy
  else navigator.serviceWorker.addEventListener('controllerchange', reload);
})();
